        let totalPoints = 0;
        if (Array.isArray(rawHistory)) {
            totalPoints = rawHistory.reduce((acc, day) => acc + (day.totalPoints || 0), 0);
        } else if (rawHistory && rawHistory.datasets) {
            totalPoints = rawHistory.datasets[0].data.reduce((acc, val) => acc + (Number(val) || 0), 0);
        }

